package com.muthumol.player.dummy;
import android.content.*;import android.widget.*;import java.util.*;
final class HistoryActions {
 static boolean hidden(Context c,Movie m){return c.getSharedPreferences("history-hidden",0).getBoolean(m.cacheIdentity(),false);}
 static void reveal(Context c,Movie m){c.getSharedPreferences("history-hidden",0).edit().remove(m.cacheIdentity()).apply();}
 static void show(MainActivity a){List<Movie> saved=a.tvLibrary.saved();if(saved.isEmpty()){Ui.message(a,"History","History is empty.");return;}List<String> names=new ArrayList<>();names.add("Clear all history");for(Movie m:saved)names.add(MediaTitle.parse(m.title).display());Ui.menu(a,"Remove history",names.toArray(new String[0]),n->{if(n==0)Ui.dialog(a).setTitle("Clear history?").setMessage("Clears this app's local positions and history. Telegram media stays. The cleared positions sync to your other app devices.").setPositiveButton("Clear",(d,w)->remove(a,saved)).setNegativeButton("Cancel",null).show();else remove(a,Collections.singletonList(saved.get(n-1)));});}
 static void remove(MainActivity a,List<Movie> movies){SharedPreferences player=a.getSharedPreferences("player",0),hidden=a.getSharedPreferences("history-hidden",0);Map<String,Long> previous=new HashMap<>();for(Movie m:movies){String pos="pos:"+m.cacheIdentity(),logical="logical-pos:"+VideoCopies.key(m);previous.put(pos,player.contains(pos)?player.getLong(pos,0):null);previous.put(logical,player.contains(logical)?player.getLong(logical,0):null);player.edit().remove(pos).putLong(logical,0).apply();a.tvLibrary.p.edit().remove("movie:"+a.tvLibrary.key(m)).apply();hidden.edit().putBoolean(m.cacheIdentity(),true).apply();WatchSync.get(a).removeHistory(m);}a.previewMovie=null;a.shelfKey=null;a.extraShelfKey="";a.changed();Ui.dialog(a).setTitle("History removed").setMessage("Telegram originals are unchanged.").setPositiveButton("Undo",(d,w)->{SharedPreferences.Editor e=player.edit();for(Map.Entry<String,Long> item:previous.entrySet()){if(item.getValue()==null)e.remove(item.getKey());else e.putLong(item.getKey(),item.getValue());}e.apply();for(Movie m:movies){a.tvLibrary.remember(m);WatchSync.get(a).record(m,m.savedPosition(a),m.duration*1000L,null);}a.shelfKey=null;a.extraShelfKey="";a.changed();}).setNegativeButton("Done",null).show();}
}
